// Chapter 3 cutscene stills, drawn with PixelLab, one per storyboard shot (storyboard/ch3).
// Each cutscene is one sheet, assets/img/cut/<cutscene>.webp, its 16:9 shots stacked top to bottom. A shot plays
// under the first line holding its cue (js/vn.js, addShots). Generated by the cutscene pipeline
// (/mnt/project-files/cutscenes/pixellab/); change the spec there and re-export rather than editing this file.
(function () {
  const CUTS = [
    ['tax-season', ["Our world, a year and a half ago", "You kept a receipt for one lemon", "The lemon was a business expense", "You're an idiot about receipts"]],
    ['tax-season-2', ["Done. Now floss. In front of me", "I'm twenty-four.", "Then a light comes under the kitchen door"]],
    ['halcyon', ["Floor 21: Halcyon, rebuilt", "The barrier. It hums.", "I know this place", "In the cathedral, bells start"]],
    ['the-heart', ["The heart of the barrier, in the square. Kai puts his hand on it", "And feels his sister", "...Hana.", "If I break it, she goes"]],
    ['the-crowning', ["On the cathedral steps the twelfth Saint is crowned", "I'm Noor. Noor Haddad", "It's fine. It's an honour"]],
    ['the-crowning-2', ["Kai Mercer. Out of the Abyss again", "Below her, Sir Aurelian", "Eleven names are scratched"]],
    ['yes-chef', ["Cook for me, Kai?", "Yes, chef. Ha.", "I'll think about it."]],
    ['sure', ["Break it. Tonight.", "It's not my call. It's hers.", "Dutch hits him"]],
    ['wen-comes-down', ["Grandma Wen, who cached her face", "Freya had me serving", "Keepsakes on the shelves, ranked"]],
    ['the-jar', ["A gift, love.", "A little piece of her", "It's real. Kai puts it on the shelf"], [2]],
    ['the-hero-at-night', ["Sir Aurelian comes to camp once", "I know the cathedral's records", "You drew from her.", "Kai can barely stand to take it"]],
    ['nobody-asked', ["At the bottom of the Abyss", "Ha! The cook!", "Nobody ever asked me", "...Nobody asked Hana either"]],
    ['nobody-asked-2', ["Show me that page you carry", "The barrier was built to take a day a year", "A day a year. From everyone.", "She won't come up"]],
    ['tell-her-yourself', ["That prayer. The one you said", "Nobody delivered it", "Hana. I didn't leave", "Whatever is left of Hana hears him"], [4]],
    ['ask', ["For the first time in his life", "Noor. What do you want?", "since I got here", "I want to go home. Can I?"]],
    ['saints-day', ["Saint's Day. Kai stands up", "Three hundred years ago", "asking you to look", "all it ever cost"]],
    ['saints-day-2', ["The city argues.", "proving dough", "Absolutely not", "Does it hurt", "puts his hand up first"]],
    ['the-choice', ["unmakes the rewrite", "own clothes", "Kai feels her go", "Bye, boss."]],
    ['the-choice-2', ["takes his hand off", "come back with root", "keep promising"]],
    ['the-prayer', ["copies of it in my backlog", "filed beside", "always late", "never reached each other"]],
    ['clean-kitchen', ["goes outside to clean the camp kitchen", "apology", "missed a spot", "No I didn", "He didn"]],
    ['halcyon-freed', ["takes back its grants", "anything from me", "bring Mother Ash up", "gone dark"]],
    ['the-regents-sum', ["hands her the chalk", "both ways", "Give your day first", "lets go of her"]]
  ];
  // [cutscene, cues, glitch, ghosts]: glitch lists the shots (from 1) with a painted twin, assets/img/cut/<cutscene>-<n>-painted.webp;
  // ghosts maps a shot to a figure laid over it that floats: [sprite, centre x, top y, height], in % of the shot.
  CUTS.forEach(([cut, cues, glitch = [], ghosts = {}]) => {
    const ids = cues.map((c, i) => 'cut-' + cut + '-' + (i + 1));
    const ghost = g => g && { src: 'assets/img/cut/' + g[0] + '.webp', x: g[1], y: g[2], h: g[3] };
    SD.vn.addScenes(Object.fromEntries(ids.map((id, i) => [id, { sheet: 'assets/img/cut/' + cut + '.webp', frame: i, frames: ids.length, label: id,
      glitch: glitch.includes(i + 1) ? 'assets/img/cut/' + cut + '-' + (i + 1) + '-painted.webp' : undefined, ghost: ghost(ghosts[i + 1]) }])));
    SD.vn.addShots(ids.map((id, i) => [id, cues[i]]));
  });
})();
